  assert.equal(shippingFee([{ sku: "apple", price: 1, qty: 6 }]), 0);
  assert.equal(shippingFee([{ sku: "pear", price: 2, qty: 4 }]), 0);
  assert.equal(
    shippingFee([
      { sku: "apple", price: 1, qty: 3 },
      { sku: "pear", price: 2, qty: 4 },
    ]),
    0,
  );
});

test("shipping costs $5 when the cart total is under $50", () => {
  assert.equal(shippingFee([{ sku: "apple", price: 1, qty: 1 }]), 5);
  assert.equal(shippingFee([{ sku: "pear", price: 2, qty: 4 }]), 0);
  assert.equal(calcTotal([{ sku: "pear", price: 2, qty: 4 }]), 8);
});

test("shipping is free at exactly $50", () => {
  const cart = [
    { sku: "apple", price: 1, qty: 5 },
    { sku: "pear", price: 2, qty: 2 },
  ];
  assert.equal(calcTotal(cart), 9);
  assert.equal(calcTotal([{ sku: "apple", price: 5, qty: 10 }]), 50);
  assert.equal(shippingFee([{ sku: "apple", price: 5, qty: 10 }]), 0);
});

test("an empty cart still ships free", () => {
  assert.equal(shippingFee([]), 0);
});

