import { test } from "node:test";
import assert from "node:assert/strict";
import { calcTotal, shippingFee } from "../src/pricing.ts";

test("shipping is free when the cart total is $50 or more", () => {
  assert.equal(calcTotal([{ sku: "crate", price: 10, qty: 5 }]), 50);
  assert.equal(shippingFee([{ sku: "crate", price: 10, qty: 5 }]), 0);
  assert.equal(shippingFee([{ sku: "crate", price: 10, qty: 6 }]), 0);
  assert.equal(
    shippingFee([
      { sku: "apple", price: 1, qty: 2 },
      { sku: "crate", price: 10, qty: 5 },
    ]),
    0,
  );
});

test("shipping costs $5 when the cart total is under $50", () => {
  assert.equal(shippingFee([{ sku: "apple", price: 1, qty: 1 }]), 5);
  assert.equal(shippingFee([{ sku: "pear", price: 2, qty: 4 }]), 5);
  assert.equal(shippingFee([{ sku: "crate", price: 10, qty: 4 }]), 5);
  assert.equal(
    shippingFee([
      { sku: "apple", price: 1, qty: 4 },
      { sku: "pear", price: 2, qty: 3 },
    ]),
    5,
  );
});

test("an empty cart still ships free", () => {
  assert.equal(shippingFee([]), 0);
});

